return "local function install(d)local okBit,bit=pcall(require,\"bit\")bit=okBit and bit or bit32 local band,bor,bxor,bnot,lshift,rshift if bit then band,bor,bxor,bnot=bit.band,bit.bor,bit.bxor,bit.bnot lshift,rshift=bit.lshift,bit.rshift end local hash=type(love)==\"table\"and love.data and love.data.hash local char,byte,concat=string.char,string.byte,table.concat local function xor8(x,y)local r,p=0,1 for _=1,8 do local a,b=x%2,y%2 if a~=b then r=r+p end x,y,p=(x-a)/2,(y-b)/2,p*2 end return r end local function toString(bytes)local parts={}for i=1,#bytes do parts[i]=char(bytes[i])end return concat(parts)end local function u32(x)return x%4294967296 end local function rrot(x,n)return u32(bor(rshift(x,n),lshift(x,32-n)))end local function lrot(x,n)return u32(bor(lshift(x,n),rshift(x,32-n)))end local function wipe(a)for i=1,#a do a[i]=0 end end local B64=\"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"local B64I={}for i=1,64 do B64I[byte(B64,i)]=i-1 end local function unb64(s)local out,acc,bits={},0,0 for i=1,#s do local v=B64I[byte(s,i)]if v then acc=(acc%262144)*64+v bits=bits+6 if bits>=8 then bits=bits-8 out[#out+1]=math.floor(acc/2^bits)%256 end end end return out end local K={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2,}local function sha256(bytes)if hash then return{byte(hash(\"sha256\",toString